package com.wheelwright.evidence.v2.portfolio;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;

/** Position-owned comparison of admitted terms and documented option cash flows; not a tax ledger. */
public final class PortfolioEconomicHistory {
 private PortfolioEconomicHistory(){}
 public static ObjectNode compare(ObjectNode original,ObjectNode current,JsonNode history,Instant now){
  var result=obj();result.set("original",period(original,false,now));result.set("current",period(current,true,now));String at=now.toString();var cumulative=obj().put("historyStatus",history.path("historyStatus").asText("UNKNOWN"));cumulative.set("from",history.has("from")?history.get("from"):NullNode.instance);cumulative.set("through",history.has("through")?history.get("through"):NullNode.instance);var events=history.path("events");cumulative.set("events",events.isArray()?events.deepCopy():array());
  boolean complete=history.path("historyStatus").asText().equals("DOCUMENTED_INTERVAL_COMPLETE")&&!history.path("from").isNull()&&!history.path("through").isNull()&&history.has("from")&&history.has("through");BigDecimal received=BigDecimal.ZERO,paid=BigDecimal.ZERO,closed=BigDecimal.ZERO,fees=BigDecimal.ZERO;boolean flowsKnown=events.isArray()&&!events.isEmpty(),feesKnown=flowsKnown;var evidence=array();var identities=new HashSet<String>();
  for(var event:events){String identity=event.at("/transaction/href").asText();if(!identity.isBlank()&&!identities.add(identity))throw new IllegalArgumentException("duplicate documented transaction");
   var opening=event.path("openingCashFlow");var closing=event.path("closingCashFlow");var fee=event.path("fee");if(!established(opening)||!established(closing)||!opening.path("unit").asText().equals("MONEY")||!closing.path("unit").asText().equals("MONEY")||!opening.path("currency").asText().equals(closing.path("currency").asText())||!opening.path("currency").asText().equals("USD"))flowsKnown=false;else{var amount=number(opening.get("value"));if(amount.signum()>0)received=received.add(amount);else paid=paid.subtract(amount);closed=closed.add(number(closing.get("value")));}
   if(!established(fee)||!fee.path("unit").asText().equals("MONEY"))feesKnown=false;else{var amount=number(fee.get("value"));if(amount.signum()<0||!fee.path("currency").asText().equals("USD"))throw new IllegalArgumentException("fee magnitude/currency invalid");fees=fees.add(amount);}for(var e:event.path("evidence"))evidence.add(e);
  }
  for(String field:List.of("openingPremiumsReceived","openingPremiumsPaid","closingCashFlows","fees","netDocumentedOptionCashFlow","realizedGrossPl","realizedNetPl","replacementCostsPaid","brokerTaxBasis"))cumulative.set(field,unknown("MONEY",at,"HISTORY_INCOMPLETE"));cumulative.set("economicBreakevenPerShare",unknown("PRICE",at,"HISTORY_INCOMPLETE"));
  // Partial histories expose documented subtotals with explicit scope; never lifetime totals.
  if(flowsKnown){cumulative.set("openingPremiumsReceived",historyMetric(received,evidence,at,complete));cumulative.set("openingPremiumsPaid",historyMetric(paid,evidence,at,complete));cumulative.set("closingCashFlows",historyMetric(closed,evidence,at,complete));if(feesKnown){cumulative.set("fees",historyMetric(fees,evidence,at,complete));cumulative.set("netDocumentedOptionCashFlow",historyMetric(received.subtract(paid).add(closed).subtract(fees),evidence,at,complete));}}
  var originalPremium=result.at("/original/paidOptionPremium");if(complete&&flowsKnown&&established(originalPremium)&&paid.compareTo(number(originalPremium.get("value")))>=0)cumulative.set("replacementCostsPaid",historyMetric(paid.subtract(number(originalPremium.get("value"))),evidence,at,true));
  var shares=leaves(original.path("composition")).stream().filter(n->n.path("kind").asText().equals("LONG_SHARES")).toList();var shareBasis=result.at("/original/shareAcquisitionBasis");if(complete&&flowsKnown&&feesKnown&&shares.size()==1&&established(shareBasis)){var count=number(shares.getFirst().path("quantity"));if(count.signum()>0)try{cumulative.set("economicBreakevenPerShare",metric(number(shareBasis.path("value")).subtract(received.subtract(paid).add(closed).subtract(fees)).divide(count),"PRICE","USD",at,"DOCUMENTED_NET_OPTION_CASH_AGAINST_ORIGINAL_SHARE_INVESTMENT_NOT_TAX_BASIS","QUALIFIED",evidence,"DOCUMENTED_HISTORY"));}catch(ArithmeticException ignored){/* Nonterminating price requires a separately defined rounding policy; remain qualified unknown. */}}
  if(established(cumulative.path("economicBreakevenPerShare")))((ArrayNode)cumulative.at("/economicBreakevenPerShare/assumptions")).add("Conditional documented-flow comparison against retained original share investment. Events outside the declared interval can change the economic result; no lifetime completeness or broker tax-basis claim.");
  // Source-admitted realized attribution and broker tax basis are distinct evidence, not inferred from cash totals.
  for(String field:List.of("realizedGrossPl","realizedNetPl","brokerTaxBasis")){var fact=history.path(field);if(established(fact)&&fact.path("unit").asText().equals("MONEY")&&fact.path("currency").asText().equals("USD")&&fact.path("origin").asText().equals("BROKER_REPORTED")&&!fact.path("evidence").isEmpty())cumulative.set(field,fact.deepCopy());}
  result.set("cumulative",cumulative);result.set("warnings",array());for(String period:List.of("original","current"))if(result.path(period).path("protectionStatus").asText().equals("UNKNOWN"))((ArrayNode)result.path("warnings")).add(warning("VALUATION_UNSUPPORTED","/"+period,"Exact retained constituent and option terms remain inspectable.","Currency, deliverable, quantity or source-term qualification does not establish protective applicability to the bound shares; no supported loss floor is asserted."));if(!complete)((ArrayNode)result.get("warnings")).add(warning("HISTORY_INCOMPLETE","/cumulative","Retained original/current terms and documented subtotals remain inspectable.","Lifetime cash flows, attribution, missing fees and tax basis are not inferred."));return result;
 }
 private static ObjectNode historyMetric(BigDecimal value,ArrayNode evidence,String at,boolean complete){var m=metric(value,"MONEY","USD",at,complete?"DOCUMENTED_COMPLETE_INTERVAL_SUM":"DOCUMENTED_PARTIAL_INTERVAL_SUBTOTAL","QUALIFIED",evidence,"DOCUMENTED_HISTORY");((ArrayNode)m.get("assumptions")).add("Documented interval sum only; completeness applies to the declared interval, not automatically the lifetime of the Position or unobserved events outside it.");if(!complete){((ArrayNode)m.get("warningCodes")).add("HISTORY_INCOMPLETE");((ArrayNode)m.get("assumptions")).add("Documented subtotal only; missing events are not zero and this is not a lifetime result.");}return m;}
 private static ObjectNode period(ObjectNode construction,boolean current,Instant now){
  String at=now.toString();var result=obj().put("asOf",construction.path("createdAt").asText()).put("protectionStatus","NONE").put("rights","COMPOSITE");result.set("construction",construction.path("self"));result.set("evidence",construction.path("evidence"));result.set("openingCashFlow",PortfolioMath.evaluate(construction,Map.of(),now).path("openingCashFlow"));result.set("shareAcquisitionBasis",na("MONEY",at));result.set("paidOptionPremium",na("MONEY",at));result.set("protectionStrike",na("PRICE",at));result.set("lossFloorGrossPl",na("MONEY",at));var terms=array();var xs=leaves(construction.path("composition"));var shares=xs.stream().filter(x->x.path("kind").asText().equals("LONG_SHARES")).toList();var options=xs.stream().filter(x->x.path("kind").asText().equals("OPTION")).toList();var longs=options.stream().filter(x->x.path("side").asText().equals("LONG")).toList();for(var x:options)terms.add(x.path("terms"));result.set("optionTerms",terms);
  if(!shares.isEmpty())result.set("shareAcquisitionBasis",sumBasis(shares,at));if(!longs.isEmpty())result.set("paidOptionPremium",sumBasis(longs,at));
  if(!xs.isEmpty()&&xs.stream().allMatch(x->x.path("kind").asText().equals("CASH")))result.put("rights","CASH");else if(options.isEmpty()&&!shares.isEmpty())result.put("rights","SHARES_OWNED");else if(xs.size()==1&&longs.size()==1&&Set.of("CALL","PUT").contains(longs.getFirst().at("/terms/right").asText()))result.put("rights",longs.getFirst().at("/terms/right").asText().equals("CALL")?"RIGHT_TO_BUY_SHARES":"RIGHT_TO_SELL_SHARES");else if(shares.isEmpty()&&options.stream().allMatch(x->x.path("side").asText().equals("SHORT")))result.put("rights","SHORT_OBLIGATION");
  var puts=longs.stream().filter(x->x.at("/terms/right").asText().equals("PUT")).toList();if(shares.size()==1&&puts.size()==1){var put=puts.getFirst();var share=shares.getFirst();var multiplier=number(put.at("/terms/multiplier"));boolean eligible=multiplier!=null&&PortfolioRecognition.standardTerms(put.path("terms"))&&Set.of("ESTABLISHED","QUALIFIED").contains(put.at("/terms/qualification").asText())&&put.path("currency").equals(share.path("currency"))&&put.at("/terms/currency").equals(share.path("currency"))&&put.at("/terms/underlying/href").equals(share.at("/instrument/href"))&&number(put.get("quantity")).multiply(multiplier).compareTo(number(share.get("quantity")))>=0;
   String expiry=put.at("/terms/expiration").asText();boolean live=!expiry.isBlank()&&!LocalDate.parse(expiry).isBefore(now.atZone(ZoneId.of("America/New_York")).toLocalDate());result.put("protectionStatus",eligible?(current&&live?"CURRENT_CONTRACTUAL":"HISTORICAL_ONLY"):"UNKNOWN");if(eligible){var strike=number(put.at("/terms/strike"));if(strike!=null)result.set("protectionStrike",metric(strike,"PRICE",put.path("currency").asText(),at,"RETAINED_CONTRACT_STRIKE","QUALIFIED",put.at("/terms/evidence")));var payoff=PortfolioMath.payoff(construction,now);if(!payoff.path("geometry").isNull()){var first=payoff.at("/geometry/segments/0");if(number(first.path("slope")).signum()==0)result.set("lossFloorGrossPl",metric(number(first.path("intercept")),"MONEY",put.path("currency").asText(),at,"STATED_HORIZON_GROSS_INTRINSIC_FLOOR_WITH_RETAINED_COSTS","QUALIFIED",payoff.path("evidence"),"OPENING_CASH_FLOW"));}else result.set("lossFloorGrossPl",unknown("MONEY",at,"VALUATION_UNSUPPORTED"));}else{result.set("protectionStrike",unknown("PRICE",at,"VALUATION_UNSUPPORTED"));result.set("lossFloorGrossPl",unknown("MONEY",at,"VALUATION_UNSUPPORTED"));}
  }return result;
 }
 private static ObjectNode sumBasis(List<ObjectNode> nodes,String at){var total=BigDecimal.ZERO;var evidence=array();for(var n:nodes){var basis=n.at("/allocation/basis");if(!established(basis)||!basis.path("unit").asText().equals("MONEY")||!basis.path("currency").asText().equals("USD")||number(basis.path("value"))==null||number(basis.path("value")).signum()<0)return unknown("MONEY",at,"BASIS_ATTRIBUTION_UNKNOWN");total=total.add(number(basis.get("value")));for(var e:basis.path("evidence"))evidence.add(e);}return metric(total,"MONEY","USD",at,"SUM_DOCUMENTED_ATTRIBUTED_ACQUISITION_MAGNITUDES","QUALIFIED",evidence,"DOCUMENTED_HISTORY");}
}
